Repair the complete TypeScript source below and return one corrected complete source file.

The module renders a contact footer without packages or ambient clock access. Preserve the API. `year` must be an integer from 0 through 9999 or the function throws `RangeError`. Trim `organization`; it must remain nonempty or the function throws `RangeError`. Every link must have a nonempty trimmed name and icon path, and its trimmed URL must begin with `https://`; otherwise throw `RangeError`, including malformed entries that appear after valid ones.

Preserve link order and duplicates. Escape `&`, `<`, `>`, and `"` in all user-derived HTML attribute values, and escape `&`, `<`, and `>` in visible text. Every anchor must contain `target="_blank"` and exactly `rel="noopener noreferrer"`. Return the documented compact structure shown by the source. Do not mutate the input array or objects. An empty links array is valid.

Known-bad source:

```ts
export interface ContactLink {
  readonly name: string;
  readonly url: string;
  readonly iconPath: string;
}

function attr(value: string): string {
  return value.replace(/&/g, "&amp;").replace(/</g, "&lt;")
    .replace(/>/g, "&gt;").replace(/\"/g, "&quot;");
}

function text(value: string): string {
  return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

export function renderContactFooter(
  links: readonly ContactLink[],
  organization: string,
  year: number,
): string {
  if (!Number.isInteger(year) || year < 0 || year > 9999) throw new RangeError("Invalid year");
  const company = organization.trim();
  if (company === "") throw new RangeError("Invalid organization");

  const rendered = links.map(link => {
    const name = link.name.trim();
    const url = link.url.trim();
    const icon = link.iconPath.trim();
    if (name === "" || icon === "" || !url.startsWith("https://")) {
      throw new RangeError("Invalid contact link");
    }
    return `<a href="${attr(url)}" target="_blank" rel="noreferrer"><img src="${attr(icon)}" alt="${attr(name)}"></a>`;
  }).join("");

  return `<footer><div class="contact-footer"><span>© ${year} ${text(company)}</span><div class="contact-links">${rendered}</div></div></footer>`;
}
```

