import { ContactLink, renderContactFooter } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function rangeError(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    assert(error instanceof RangeError, `${message}: wrong error type`);
    return;
  }
  throw new Error(`${message}: did not throw`);
}

const links: ContactLink[] = [
  { name: ' Docs & "Help" ', url: ' https://example.com/?a=1&b="x" ', iconPath: ' /icons/<doc>&".svg ' },
  { name: "Docs & Help", url: "https://example.com/two", iconPath: "/two.svg" },
  { name: "Docs & Help", url: "https://example.com/two", iconPath: "/two.svg" },
];
const snapshot = JSON.stringify(links);
const rendered = renderContactFooter(links, " ACME & <Partners> ", 0);
const expected = '<footer><div class="contact-footer"><span>© 0 ACME &amp; &lt;Partners&gt;</span><div class="contact-links">' +
  '<a href="https://example.com/?a=1&amp;b=&quot;x&quot;" target="_blank" rel="noopener noreferrer"><img src="/icons/&lt;doc&gt;&amp;&quot;.svg" alt="Docs &amp; &quot;Help&quot;"></a>' +
  '<a href="https://example.com/two" target="_blank" rel="noopener noreferrer"><img src="/two.svg" alt="Docs &amp; Help"></a>' +
  '<a href="https://example.com/two" target="_blank" rel="noopener noreferrer"><img src="/two.svg" alt="Docs &amp; Help"></a>' +
  '</div></div></footer>';
assert(rendered === expected, `unexpected compact footer: ${rendered}`);
assert(JSON.stringify(links) === snapshot, "input links were mutated");
assert(renderContactFooter([], "Org", 9999) === '<footer><div class="contact-footer"><span>© 9999 Org</span><div class="contact-links"></div></div></footer>', "empty links and maximum year");

rangeError(() => renderContactFooter([], "Org", -1), "year lower bound");
rangeError(() => renderContactFooter([], "Org", 10000), "year upper bound");
rangeError(() => renderContactFooter([], "Org", 1.5), "integer year");
rangeError(() => renderContactFooter([], "   ", 2026), "empty organization");
rangeError(() => renderContactFooter([{ name: " ", url: "https://ok", iconPath: "x" }], "Org", 2026), "empty link name");
rangeError(() => renderContactFooter([{ name: "x", url: "http://bad", iconPath: "x" }], "Org", 2026), "non-HTTPS URL");
rangeError(() => renderContactFooter([{ name: "x", url: "https://ok", iconPath: " " }], "Org", 2026), "empty icon");
rangeError(() => renderContactFooter([
  { name: "valid", url: "https://ok", iconPath: "ok.svg" },
  { name: "invalid", url: "ftp://bad", iconPath: "bad.svg" },
], "Org", 2026), "malformed later entry");

